package com.slime;
import android.content.Context; import java.io.*; import java.util.*; import org.json.*;
public class MemoryManager { Context ctx; File chatFile, longFile, notifFile; public MemoryManager(Context c){ ctx=c; chatFile=new File(c.getFilesDir(),"chats.json"); longFile=new File(c.getFilesDir(),"long_memory.json"); notifFile=new File(c.getFilesDir(),"notifs.json"); }
 public void saveChat(String user, String slime){ try{ JSONArray arr=loadChats(); JSONObject obj=new JSONObject(); obj.put("u",user); obj.put("s",slime); obj.put("t",System.currentTimeMillis()); arr.put(obj); if(arr.length()>120){ JSONArray n=new JSONArray(); for(int i=arr.length()-120;i<arr.length();i++) n.put(arr.get(i)); arr=n; } FileWriter fw=new FileWriter(chatFile); fw.write(arr.toString()); fw.close(); }catch(Exception e){} }
 public JSONArray loadChats(){ try{ if(!chatFile.exists()) return new JSONArray(); BufferedReader br=new BufferedReader(new FileReader(chatFile)); StringBuilder sb=new StringBuilder(); String l; while((l=br.readLine())!=null) sb.append(l); br.close(); return new JSONArray(sb.toString()); }catch(Exception e){ return new JSONArray(); } }
 public String getRecentContext(int n){ try{ JSONArray arr=loadChats(); StringBuilder sb=new StringBuilder(); int start=Math.max(0,arr.length()-n); for(int i=start;i<arr.length();i++){ JSONObject o=arr.getJSONObject(i); sb.append("U:").append(o.optString("u")).append(" | S:").append(o.optString("s")).append("\n"); } return sb.toString(); }catch(Exception e){ return ""; } }
 public String getLongContext(){ try{ if(!longFile.exists()) return ""; BufferedReader br=new BufferedReader(new FileReader(longFile)); StringBuilder sb=new StringBuilder(); String l; while((l=br.readLine())!=null) sb.append(l); br.close(); return sb.toString(); }catch(Exception e){ return ""; } }
 public void saveLongFact(String fact){ try{ String cur=getLongContext(); FileWriter fw=new FileWriter(longFile); fw.write(cur+"\n- "+fact); fw.close(); }catch(Exception e){} }
 public void saveNotif(String title,String text){ try{ JSONArray arr=new JSONArray(); if(notifFile.exists()){ BufferedReader br=new BufferedReader(new FileReader(notifFile)); StringBuilder sb=new StringBuilder(); String l; while((l=br.readLine())!=null) sb.append(l); br.close(); try{ arr=new JSONArray(sb.toString()); }catch(Exception e){} } JSONObject obj=new JSONObject(); obj.put("title",title); obj.put("text",text); obj.put("t",System.currentTimeMillis()); arr.put(obj); if(arr.length()>30){ JSONArray n=new JSONArray(); for(int i=arr.length()-30;i<arr.length();i++) n.put(arr.get(i)); arr=n; } FileWriter fw=new FileWriter(notifFile); fw.write(arr.toString()); fw.close(); }catch(Exception e){} }
 public String getNotifContext(){ try{ if(!notifFile.exists()) return ""; BufferedReader br=new BufferedReader(new FileReader(notifFile)); StringBuilder sb=new StringBuilder(); String l; while((l=br.readLine())!=null) sb.append(l); br.close(); JSONArray arr=new JSONArray(sb.toString()); StringBuilder out=new StringBuilder(); for(int i=Math.max(0,arr.length()-8);i<arr.length();i++){ JSONObject o=arr.getJSONObject(i); out.append(o.optString("title")).append(": ").append(o.optString("text")).append("\n"); } return out.toString(); }catch(Exception e){ return ""; } }
}
